'use strict';
const S=MaisonSim,M=MaisonMusic,D=MaisonDecisions,I=MaisonIdentity,W=MaisonWeeks,H=MaisonHouse,T=MaisonShows,R=MaisonMorale,$=s=>document.querySelector(s),STORE='maison-accords-v1';
let state=S.create(3),selected='lea',running=false,speed=1,filter='all',saved=false,dialogWasRunning=false,toastTimer,positions={},accumulator=0,dialogOnClose=null;
try{const raw=JSON.parse(localStorage.getItem(STORE));if(raw&&[1,2].includes(raw.version)&&Array.isArray(raw.people)&&raw.people.length>=3&&raw.people.length<=6&&raw.people.every(p=>S.PEOPLE.some(x=>x.id===p.id)&&S.ACTIONS[p.action])){if(raw.version===1)localStorage.setItem('maison-accords-backup-v1',JSON.stringify(raw));state=M.init(raw,true);saved=true;}}catch(e){}
H.init(state);W.init(state,true);T.init(state);globalThis.MaisonJourney?.init(state);T.ensureDue(state);R.init(state);globalThis.MaisonHouseEvents?.init(state);
const rooms=H.rooms;
const roomName=Object.fromEntries(Object.entries(rooms).map(([id,r])=>[id,'· '+r.label]));
const actionIcon={toilet:'WC',party:'✦',rest:'☁',compose:'✎',practice:'♫',jam:'♪',talk:'☕'};
function clock(tick){const total=W.total(state,tick);return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function day(tick){return W.week(state,tick);}
function save(){if(!saved)return;try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){$('#saveStatus').hidden=false;$('#saveStatus').textContent='Sauvegarde indisponible dans ce navigateur';}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function avatar(p){return I.portrait(p);}
function tags(p){return p.traits.map(t=>`<span class="tag" tabindex="0" title="${S.TRAITS[t]}">${t}</span>`).join('');}
function setRunning(value){running=value&&!window.homeOpen&&!$('#dialog').open&&!W.blocked(state);$('#pause').textContent=running?'Ⅱ':'▶';$('#pause').setAttribute('aria-label',running?'Mettre en pause':'Lancer la simulation');$('#houseState').textContent=T.busy(state)?(T.blocking(state)?'En sortie':'Journée de show'):running?'La vie suit son cours':'En pause';$('#runningDot').style.background=running?'#7a9d67':'#bd9b69';}
let lastPersonClick={id:null,time:-1000};
function select(id){selected=id;renderProfile();document.querySelectorAll('.roster-item,.person').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));}
function personClick(id){const now=performance.now(),double=lastPersonClick.id===id&&now-lastPersonClick.time<350;lastPersonClick={id,time:now};select(id);if(double)showPerson(id);}
function bindPerson(el,id){el.onclick=()=>personClick(id);el.ondblclick=()=>showPerson(id);el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();select(id);showPerson(id);}};}
function activity(p){if(T.busy(state))return T.activity(state);return p.waking?'Se réveille':p.sleeping?'Dort':p.travel>0?'En route':S.ACTIONS[p.action].label+(p.room==='patio'?' · Patio':'');}
function renderRoster(){ $('#residents').textContent=`${state.people.length} / 6`;$('#count').textContent=String(state.people.length).padStart(2,'0');$('#roster').style.setProperty('--members',state.people.length);$('#roster').innerHTML=state.people.map(p=>`<button class="roster-item ${p.id===selected?'selected':''}" data-id="${p.id}" aria-pressed="${p.id===selected}" title="${p.name} · ${p.instrument} · double-clic pour sa fiche">${avatar(p)}<span class="roster-text"><strong>${I.icons[p.instrument]||'♪'} ${p.name}${p.id===state.playerId?' · Toi':''}</strong></span>${I.vitals(p)}${window.MaisonPersonActivityUI?.compact(p)||''}</button>`).join('');$('#roster').querySelectorAll('button').forEach(b=>{bindPerson(b,b.dataset.id);b.setAttribute('aria-controls','rosterExpansion');b.setAttribute('aria-expanded','false');b.onclick=()=>{personClick(b.dataset.id);window.MaisonPersonActivityUI?.toggle(b.dataset.id);};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(b.dataset.id);window.MaisonPersonActivityUI?.toggle(b.dataset.id);}};});window.MaisonPersonActivityUI?.render();for(let i=1;i<=6;i++){const people=H.occupants(state,'bedroom'+i);$('#bedroomNames'+i).textContent=people.map(p=>p.name).join(' & ')||'Libre';}}
function renderProfile(){const p=state.people.find(x=>x.id===selected)||state.people[0];selected=p.id;$('#openSelected').textContent=p.name+' · '+p.instrument+' · Fiche complète ↗';$('#openSelected').onclick=()=>showPerson(p.id);}
function showPerson(id){const p=state.people.find(x=>x.id===id);if(!p)return;if($('#dialog').open&&$('#personSheet')?.dataset.id===id)return;const projects=state.music.songs.filter(x=>x.authors.includes(id)),roommates=H.occupants(state,p.bedroomId).filter(q=>q.id!==id),intent=p.intent&&p.intent.until>state.tick;openDialog(`<div id="personSheet" class="person-sheet" data-id="${p.id}"><div class="person-sheet-header">${avatar(p)}<div><span class="eyebrow">LE COLLECTIF · ${I.esc(H.rooms[p.bedroomId].label)}</span><h2>${p.name}<span class="dot">.</span></h2><p>${p.instrument} <span>·</span> ${p.style}</p></div><div class="sheet-energy"><b>${Math.round(p.energy)}<small>/100</small></b><span>ÉNERGIE</span></div></div><nav class="person-tabs" aria-label="Sections de la fiche"><button data-person-tab="portrait" class="active" aria-pressed="true">Portrait</button><button data-person-tab="music" aria-pressed="false">Musique · ${projects.length}</button><button data-person-tab="relations" aria-pressed="false">Liens · ${state.people.length-1}</button></nav>
<div class="person-tab-panel portrait-panel" data-person-panel="portrait"><div class="person-facts"><div><span>MAINTENANT</span><strong>${activity(p)}</strong><small>${I.esc(rooms[p.room]?.label||'Dans la maison')}</small></div><div><span>HUMEUR</span><strong>${p.mood||'À son rythme'}</strong><small>${p.sleeping?'Récupère jusqu’à 8 h':p.nightAction?'Veille cette nuit':intent?'Une intention en tête':'Libre de ses envies'}</small></div><div><span>SA CHAMBRE</span><strong>${I.esc(H.rooms[p.bedroomId].label)}</strong><small>${roommates.length?'Avec '+roommates.map(q=>I.esc(q.name)).join(', '):'Chambre individuelle'}</small></div></div><section class="sheet-section personality-sheet"><h3>Sa personnalité</h3><div class="trait-grid">${p.traits.map(t=>`<div><span class="tag">${t}</span><p>${I.esc(S.TRAITS[t])}</p></div>`).join('')}</div></section>${I.moraleDetails(p)}<div class="person-wish"><span>CE QUI L’ANIME</span><p>« ${I.esc(p.want)} »</p></div>${intent?`<section class="sheet-section intention-sheet"><h3>Son intention</h3><strong>${I.esc(p.intent.label)}</strong><p>${p.intent.startTick>state.tick?'Après le réveil à 8 h':!p.intent.applied?'En attente de la fin de son activité':'Oriente ses choix'} · jusqu’à ${clock(p.intent.until)}.</p></section>`:''}${p.lastResponse?`<section class="sheet-section portrait-response"><h3>Sa dernière réponse · S${day(p.lastResponse.tick)}</h3><strong class="${p.lastResponse.accepted?'accepted':'declined'}">${p.lastResponse.accepted?'✓ Accepte':'× Refuse'} · ${I.esc(p.lastResponse.title)}</strong><p>${I.esc(p.lastResponse.reason)}</p></section>`:''}</div>
<div class="person-tab-panel" data-person-panel="music" hidden><section class="sheet-section"><h3>Ses compositions · ${M.composer(p).name}</h3><p>${(p.completedCompositions||[]).length} chansons terminées avec sa contribution. Chaque chanson compte une seule fois. Les archives restent sa propriété.</p><h3>Carnet personnel <span>${projects.length}</span></h3><div class="personal-songs">${projects.length?projects.map(x=>`<button data-person-song="${x.id}"><span><strong class="song-heading">${I.songTitle(x)}</strong><small>${x.genre} · ${x.authors.length>1?'Avec '+x.authors.filter(a=>a!==id).map(a=>state.people.find(q=>q.id===a)?.name).join(', '):'Composition solo'}</small></span><span class="personal-song-status">${x.archived?'Archivée · droits conservés':M.ready(x)?'✓ Prête':x.adopted?'Adoptée · '+x.preparation+' %':x.votes.length?'À retravailler':x.progress>=80?'À proposer':Math.round(x.progress)+' % écrite'}${I.songStats(x)}</span></button>`).join(''):'<p>Aucune composition pour le moment.</p>'}</div></section><section class="sheet-section"><h3>Ses influences</h3><div class="influence-tags"><span>${p.style} · univers de départ</span>${p.interests.map(g=>`<span>↗ ${g} · découvert</span>`).join('')}</div><p>${Object.keys(p.influences).filter(g=>!p.interests.includes(g)).length?'Écoute en cours : '+Object.keys(p.influences).filter(g=>!p.interests.includes(g)).join(', '):'Ses rencontres pourront lui faire découvrir d’autres styles.'}</p></section><section class="sheet-section"><h3>Son paquet <span>${p.deck.length} cartes</span></h3>${I.deck(p)}<p class="hint">${I.stageEnergy(p)}</p><p class="tiny">Toutes ses cartes rejoignent la pioche commune du concert. Les coûts utilisent l’énergie par tour de la chanson.</p></section></div>
<div class="person-tab-panel" data-person-panel="relations" hidden><section class="sheet-section"><h3>Ses liens dans la maison</h3><div class="person-relations">${state.people.filter(q=>q.id!==id).map(q=>{const v=S.affinity(state,p.id,q.id);return `<button data-related-person="${q.id}" class="${v<=-3?'tense':''}">${avatar(q)}<span><strong>${q.name}</strong><small>${q.instrument}${q.bedroomId===p.bedroomId?' · même chambre':''}</small></span><span class="relationship-name">${S.relationLabel(v)} <b>↗</b></span></button>`;}).join('')}</div></section></div>
${state.partyVisitors?.some(v=>!v.leaving)?'<button id="inviteRoomGuest" class="quiet">Inviter un visiteur dans sa chambre ↗</button>':''}</div>`);if($('#inviteRoomGuest'))$('#inviteRoomGuest').onclick=()=>window.MaisonLivingUI.invite(p);$('#dialogContent').querySelectorAll('[data-person-tab]').forEach(b=>b.onclick=()=>{$('#dialogContent').querySelectorAll('[data-person-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});$('#dialogContent').querySelectorAll('[data-person-panel]').forEach(panel=>panel.hidden=panel.dataset.personPanel!==b.dataset.personTab);});$('#dialogContent').querySelectorAll('[data-person-song]').forEach(b=>b.onclick=()=>window.MaisonMusicUI.showSong(b.dataset.personSong));$('#dialogContent').querySelectorAll('[data-related-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.relatedPerson));}

function renderLogs(){const types={social:['social','tension','influence','arrival'],music:['music','song','influence'],choice:['choice','event']};const logs=state.logs.filter(l=>filter==='all'||types[filter]?.includes(l.type));$('#logs').innerHTML=logs.length?(window.MaisonPages?.slice('journal',logs.slice(0,35),4)||logs.slice(0,35)).map(l=>`<div class="log ${l.type}"><time title="Semaine ${day(l.tick)}">${clock(l.tick)}</time><span class="log-icon">${({social:'♡',tension:'↯',music:'♪',song:'✧',influence:'↗',choice:'↪',event:'♫',home:'⌂',arrival:'＋'})[l.type]||'·'}</span><div><strong>${l.title}</strong><p>${I.songText(state,l.body)}</p></div></div>`).join(''):'<p class="tiny">Les premières histoires apparaîtront ici.</p>';if(window.MaisonPages){$('#logs').innerHTML='<div class="page-items">'+$('#logs').innerHTML+'</div>'+(logs.length?window.MaisonPages.nav('journal'):'');window.MaisonPages.bind($('#logs'),renderLogs);}}
function renderCharacters(){state.people.forEach((p,i)=>{let el=document.querySelector(`.person[data-id="${p.id}"]`);if(!el){el=document.createElement('button');el.className='person';el.dataset.id=p.id;el.style.cssText=`--c:${p.color};--skin:${p.skin};--hair:${p.hair}`;el.innerHTML=`<span class="legs"></span><span class="body"></span><span class="head"></span><span class="bubble"></span><span class="name">${p.name}</span><img class="held-instrument" alt=""><span class="playing-hands"></span>`;bindPerson(el,p.id);$('#characters').append(el);}el.querySelector('.name').innerHTML=`${I.icons[p.instrument]||'♪'} ${I.esc(p.name)}`;const playing=!p.travel&&['practice','jam'].includes(p.action);el.classList.toggle('playing-instrument',playing);el.classList.toggle('selected',p.id===selected);el.setAttribute('aria-label',`${p.name}, ${p.instrument}, ${p.waking?'Se réveille':p.sleeping?'Dort':S.ACTIONS[p.action].label}`);el.title=`${p.name} · ${p.instrument} · ${p.waking?'Se réveille':p.sleeping?'Dort':S.ACTIONS[p.action].label}`;const held=el.querySelector('.held-instrument');held.src=I.instrumentAsset(p.instrument);held.alt=p.instrument;const carrying=['packing','departing','returning','unpacking'].includes(state.tour.active?.phase);held.hidden=!carrying&&(!playing||['Batterie','Clavier','Percussions'].includes(p.instrument));el.classList.toggle('carrying-instrument',carrying);el.querySelector('.bubble').innerHTML=T.busy(state)?(state.tour.active.phase==='coffee'?'☕':state.tour.active.phase==='preparing'?'☀':'♫'):p.waking?'☀':p.sleeping?'☾':p.mood==='Frustré'?'↯':playing?'♪':p.mood==='Inspiré'?'✧':actionIcon[p.action];const dest=H.position(state,p);if(!positions[p.id]){const origin=state.calendar.wake?.fromRooms?.[p.id]||p.room;const start=H.position(state,{...p,room:origin});positions[p.id]={x:start[0],y:start[1],room:origin,target:dest,queue:[],el};}let pos=positions[p.id];if(!T.blocking(state)&&pos.room!==p.room){pos.queue=H.path(pos.room,p.room,dest);pos.room=p.room;}else if(!T.blocking(state)&&pos.target&&(pos.target[0]!==dest[0]||pos.target[1]!==dest[1]))pos.queue=[dest];pos.target=dest;el.style.left=pos.x/H.WIDTH*100+'%';el.style.top=pos.y/H.HEIGHT*100+'%';});}
function render(){ $('#day').textContent='SEMAINE '+String(day(state.tick)).padStart(2,'0');$('#clock').textContent=clock(state.tick);const h=W.minute(state)/60;$('#weather').textContent=h<8?'☾ Nuit':h<10?'☀ Matin calme':h<17?'☀ Plein jour':'◐ Soirée';renderRoster();renderProfile();renderCharacters();window.MaisonGarageUI?.render();window.MaisonGuidanceUI?.render();renderLogs();window.MaisonMusicUI?.render();const waiting=state.music.orders.filter(o=>o.status==='waiting').length;$('#activityCount').textContent=waiting?waiting+' proposition(s) en attente':'Journal et propositions';window.MaisonRailUI?.render();window.MaisonTourUI?.render();window.MaisonWeeksUI?.render();window.MaisonDecisionsUI?.render();window.MaisonJourneyUI?.render();window.MaisonLivingUI?.render();window.MaisonHouseEventsUI?.render();window.MaisonViewport?.schedule();}
function openDialog(html,onClose=null){const alreadyOpen=$('#dialog').open;if(!alreadyOpen)dialogWasRunning=running;setRunning(false);const previous=alreadyOpen?dialogOnClose:null;dialogOnClose=null;if(previous)previous();dialogOnClose=onClose;$('#dialogContent').innerHTML=html;if(!alreadyOpen)$('#dialog').showModal();window.MaisonCompactDialog?.schedule();}
function closeDialog(resume=dialogWasRunning){if(!$('#dialog').open)return;const callback=dialogOnClose;dialogOnClose=null;if(callback)callback();dialogWasRunning=resume;window.MaisonDecisionsUI?.defer();$('#dialog').close();setRunning(resume);}
$('#closeDialog').onclick=()=>closeDialog();$('#dialog').addEventListener('close',()=>{if($('#dialog').open)return;const callback=dialogOnClose;dialogOnClose=null;if(callback)callback();window.MaisonDecisionsUI?.defer();setRunning(dialogWasRunning);});
function showHelp(){openDialog(`<span class="eyebrow">BIENVENUE À LA MAISON</span><div class="dialog-mark">⌂ ♪</div><h2>Laissons-les se rencontrer.</h2><p>Une maison aménagée, un garage pour répéter et des musiciens qui ont chacun leur façon d’être. Choisis ton parcours, prépare les récompenses annoncées et réussis le show majeur de l’arc. Trois échecs mettent fin à l’aventure.</p><div class="help-grid"><div><strong>01 · Une journée représente une semaine</strong><p>De 8 h à minuit, observe la maison. À 10 h et 17 h, choisis une direction. À minuit, fais le bilan et prépare la suite. Double-clique sur un habitant pour ouvrir sa fiche : personnalité, musique et relations. Ses trois traits et son moral orientent ses choix. L’énergie et le moral sont visibles sous chaque musicien. Survole un tag pour voir son effet.</p></div><div><strong>02 · Crée des occasions</strong><p>Propose une jam, un café ou une activité en duo. Ils peuvent accepter ou refuser. Les rencontres répétées font évoluer les relations et les goûts musicaux.</p></div><div><strong>03 · Fais grandir le collectif</strong><p>Commence avec trois habitants. Certaines destinations donnent une rencontre : une semaine d’essai précède le vote du groupe et la décision du candidat. Les chansons peuvent être écrites en solo ou à plusieurs. À 80 %, propose-les au groupe; après adoption, prépare-les pour la scène.</p></div></div><div class="hint">Après le choix de minuit, les dormeurs regagnent leur chambre. La nuit accélère jusqu’au bilan de 8 h; les volontaires peuvent veiller. Les décisions importantes ouvrent une fenêtre. Les influences apparaissent cinq secondes au-dessus de la maison, sans pause. Un mois compte quatre semaines. Un show a lieu à la fin des mois 2, 4, 6… (semaines 8, 16, 24…), avec préparation au réveil, café ensemble et départ à 11 h. À 22 h, ils rentrent, rangent leurs instruments puis retrouvent leur soirée. Le prochain parcours se choisit le matin suivant le show. Les récompenses sont annoncées avant de choisir une destination. Le calendrier annonce les styles probables du public, avec une part d’inconnu. Après une carte, tu vois les réponses de chacun. Les propositions différées restent dans « Activité de la maison » et démarrent automatiquement une fois disponibles. Départ : 2 Notes et 1 spéciale par musicien. Après une adoption, chaque auteur peut ajouter une carte parmi ses trois spéciales BandLive. La préparation à 100 % ne donne pas de carte supplémentaire. Toutes les cartes forment la pioche commune du concert. Énergie personnelle : 61–100 sans malus, 31–60 −2 puissance, 0–30 −3 puissance; minimum 0. Les coûts utilisent l’énergie par tour de la chanson.</div><button class="primary" id="startLife">${saved?'Retour à la maison':'Entrer dans la maison'} →</button>`);$('#startLife').onclick=()=>{dialogWasRunning=true;closeDialog();};}

$('#help').onclick=showHelp;$('#pause').onclick=()=>{if(globalThis.MaisonJourney?.blocked(state)){window.MaisonJourneyUI?.open();return;}if(T.blocking(state)){window.MaisonTourUI?.showCurrent();return;}if(W.blocked(state))window.MaisonWeeksUI?.showPending();else setRunning(!running);};$('.playback').querySelectorAll('.speed').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('active',x===b));});$('#logFilter').onchange=e=>{filter=e.target.value;renderLogs();};
function newGameDialog(){window.MaisonStartUI?.newGame();}
$('#newGame').onclick=newGameDialog;
let last=performance.now();function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;const pace=window.MaisonNightUI?.pace(dt)||{rate:speed,walk:speed};if(running&&!document.hidden){if(pace.rate===0)accumulator=0;else accumulator+=dt*pace.rate;while(running&&accumulator>=1.6){accumulator-=1.6;S.step(state);render();if(state.tick%3===0||W.blocked(state))save();if(W.blocked(state)){setRunning(false);break;}}for(const pos of Object.values(positions)){if(!running||T.blocking(state))break;let budget=dt*pace.walk*300;while(pos.queue.length&&budget>0){const [x,y]=pos.queue[0],dx=x-pos.x,dy=y-pos.y,d=Math.hypot(dx,dy);if(d<=budget){pos.x=x;pos.y=y;pos.queue.shift();budget-=d;}else{pos.x+=dx/d*budget;pos.y+=dy/d*budget;budget=0;}}pos.el.classList.toggle('moving',pos.queue.length>0);pos.el.style.left=pos.x/H.WIDTH*100+'%';pos.el.style.top=pos.y/H.HEIGHT*100+'%';}}if(!window.homeOpen){window.MaisonTourUI?.frame(dt);window.MaisonLivingUI?.frame(dt);window.MaisonJourneyUI?.maybeShow();}requestAnimationFrame(frame);}
window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['BUTTON','INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();setRunning(!running);}});render();setRunning(false);requestAnimationFrame(frame);
